const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
// 1. Geometry & Time Definitions
const kabul = ee.Geometry.Point([69.2075, 34.5553]);  // Kabul coordinates
const radiusMeters = 30 * 1609.34;  // Convert 30 miles to meters
const region = kabul.buffer(radiusMeters);

const feb2017 = ee.DateRange('2017-02-01', '2017-03-01');
const feb2018 = ee.DateRange('2018-02-01', '2018-03-01');

// 2. Data Acquisition - Use MODIS Terra Snow Cover Daily (MOD10A1)
// Band 'NDSI_Snow_Cover' represents snow cover percentage (0-100)
function getSnowCollection(dateRange) {
    return ee.ImageCollection('MODIS/061/MOD10A1')
        .filterBounds(region)
        .filterDate(dateRange)
        .select('NDSI_Snow_Cover')
        .map(function(img) {
            // Mask out non-snow pixels (values < 15) and clouds/water (values > 100)
            return img.updateMask(img.gte(15).and(img.lte(100)));
        });
}

const snow2017 = getSnowCollection(feb2017);
const snow2018 = getSnowCollection(feb2018);

// Check collection sizes
const count2017 = snow2017.size().getInfo();
const count2018 = snow2018.size().getInfo();
print(`2017 Images: ${count2017}, 2018 Images: ${count2018}`);

if (count2017 === 0 || count2018 === 0) {
    print("C1");
    return;
}

// 3. Processing - Compute mean snow cover for each period
function computeSnowMean(collection) {
    const meanImg = collection.mean();

    // Count valid pixels
    const pixelCount = meanImg.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e9
    }).get('NDSI_Snow_Cover').getInfo();

    const meanValue = meanImg.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e9
    }).get('NDSI_Snow_Cover').getInfo();

    return {count: pixelCount, value: meanValue};
}

const stats2017 = computeSnowMean(snow2017);
const stats2018 = computeSnowMean(snow2018);

print(`2017: ${stats2017.value ? stats2017.value.toFixed(1) : 'No data'}, Valid pixels: ${stats2017.count}`);
print(`2018: ${stats2018.value ? stats2018.value.toFixed(1) : 'No data'}, Valid pixels: ${stats2018.count}`);

// 4. Validation
if (stats2017.count === 0 || stats2018.count === 0) {
    print("C2");
} else if (stats2017.value === null || stats2018.value === null ||
           isNaN(stats2017.value) || isNaN(stats2018.value)) {
    print("C3");
} else {
    // Compare snow cover (higher mean = more snow)
    if (stats2018.value > stats2017.value) {
        print("A");
    } else {
        print("B");
    }
}
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
